#!/usr/bin/env python3
# apply_tvx_v1.py — TVX_V1_20261007
# ============================================================================
# TradingView-alert PAPER strategy for MCX crude options ("TV Alerts" page).
# Self-contained: carries every payload. RUN ONLY THIS SCRIPT — do not place
# any of the files by hand first (the mixed-state guard will abort).
#
#   cd ~/dev/scalp-app && python3 apply_tvx_v1.py            # apply
#   python3 apply_tvx_v1.py --dry-run                        # all checks, no writes
#   python3 apply_tvx_v1.py --allow-dirty                    # edited files have local changes
#
# NEW   backend/app/engine/tvx/{__init__,tvx_core,tvx_repo,tvx_engine,test_tvx}.py
#       backend/app/api/tvx_routes.py
#       frontend/src/pages/TvAlerts.jsx
#       docs/TVX_V1.md
# EDIT  backend/app/api_server.py   router import + admin-gated include + launch block
#       frontend/src/App.jsx        import, admin-only route, nav item (icon-only
#                                   in compact nav), shortcut T
# Mirrors into desktop/src-tauri/{backend,frontend} when those build copies exist.
#
# Gates (any failure = nothing written): fence not present · anchors unique ·
# git status clean on edited files · payload sha256 · py_compile · the TVX
# suite run in a scratch copy of backend/ · esbuild parse of both JSX files
# (when esbuild is installed) · staged all-or-nothing writes with .bak-FENCE.
# No fleet engine, shared table or Kite socket is touched. Idles until
# enabled on the TV Alerts page.
# ============================================================================

import argparse, base64, hashlib, os, py_compile, shutil, subprocess, sys, tempfile
from pathlib import Path

FENCE = "TVX_V1_20261007"
PAYLOADS = {
    'backend/app/engine/tvx/__init__.py': ('IyDilIDilIAgVFZYX1YxXzIwMjYxMDA3IOKUgOKUgCBUcmFkaW5nVmlldy1hbGVydCBwYXBlciBzdHJhdGVneSAoTUNYIGNydWRlIG9wdGlvbnMpCg==',
        'af901d8766288a443e09dd0bf83f0e5788717276708b6e6e5d11ab3c6ad82d97'),
    'backend/app/engine/tvx/tvx_core.py': ('',
        '78aa04dd1970cd28ddbb7cd6c689ec251c11bfb87ce72448148f6eaf3fc3c1bb'),
    'backend/app/engine/tvx/tvx_repo.py': ('',
        'da6fd1c82e914c996a02afdb3bcac98b02dd71f53f551fbd1b132fd93fc32ffd'),
    'backend/app/engine/tvx/tvx_engine.py': ('',
        '35a10faf1c5c0ffea895a971b549ffe6f060a8fdeaa3aa26347ffff618690652'),
    'backend/app/engine/tvx/test_tvx.py': ('',
        '290c0a5dc5f594ddd4956b8f1a998a03719aa0526b231653fad1bee0e4fa9f5b'),
    'backend/app/api/tvx_routes.py': ('',
        'b924a647586ec01f7e75d142a2b6777a902f5bf3f26117336787a2037a0932e9'),
    'frontend/src/pages/TvAlerts.jsx': ('',
        'd2394b3a7473cc18de816348b60bc60613c3609bd6b1d78d2530d238a6ff68c9'),
    'docs/TVX_V1.md': ('',
        'df8afc1a1145c66a3ad5ac7a79ceafa76497b15f076a42e096af83fa8a605546'),
}

EDITS = {
    "backend/app/api_server.py": [
        ("from app.api.closed_recent_routes import router as closed_recent_router   # ── CLOSED_RECENT_FLEET_20260921 ──\n",
         "from app.api.closed_recent_routes import router as closed_recent_router   # ── CLOSED_RECENT_FLEET_20260921 ──\n"
         "from app.api.tvx_routes import router as tvx_router   # ── TVX_V1_20261007 ──\n"),
        ("app.include_router(brk_state_router)\n",
         "app.include_router(brk_state_router)\n"
         "app.include_router(tvx_router, dependencies=[Depends(_require_admin_ui)])   # ── TVX_V1_20261007 ── TV Alerts (admin)\n"),
        ("    # ── BRK_V1 END ──\n\n    # --------------------------------------------------\n    # BROKER RECONCILIATION\n",
         "    # ── BRK_V1 END ──\n"
         "\n"
         "    # ── TVX_V1_20261007 BEGIN ── TradingView-alert PAPER strategy (MCX crude\n"
         "    # options, buy-only). Own daemon thread, own tvx_* tables, REST quotes on\n"
         "    # the data session (no new socket); touches no shared fleet path. Idles\n"
         "    # until enabled on the TV Alerts page. Own _boot_guard.\n"
         "    with _boot_guard(\"launch TVX_V1\"):\n"
         "        from app.engine.tvx.tvx_engine import start_tvx\n"
         "        start_tvx(zerodha_manager)\n"
         "        write_audit_log(\"[SYSTEM] TVX_V1 thread launched (idle until enabled)\")\n"
         "    # ── TVX_V1_20261007 END ──\n"
         "\n"
         "    # --------------------------------------------------\n"
         "    # BROKER RECONCILIATION\n"),
    ],
    "frontend/src/App.jsx": [
        ('import CryptoLab from "./pages/CryptoLab";   // ── CRYPTO_LAB ──\n',
         'import CryptoLab from "./pages/CryptoLab";   // ── CRYPTO_LAB ──\n'
         'import TvAlerts from "./pages/TvAlerts";   // ── TVX_V1_20261007 ──\n'),
        ("// ── CRYPTO_LAB END ──\n",
         "// ── CRYPTO_LAB END ──\n"
         "\n"
         "// ── TVX_V1_20261007 ── TV Alerts (TradingView-alert paper trades): admin-only,\n"
         "// fail-closed while loading, same rationale as Backtest.\n"
         "function AdminOnlyTvAlerts() {\n"
         "  const { loaded, isAdminUi } = useEntitlements();\n"
         "  if (!loaded) return null;\n"
         "  if (!isAdminUi) return <Dashboard />;\n"
         "  return <TvAlerts />;\n"
         "}\n"),
        ('    { path: "/crypto-lab",   label: "Crypto Lab",   icon: "🪙", shortcut: "Y" },   /* ── CRYPTO_LAB ── */\n',
         '    { path: "/crypto-lab",   label: "Crypto Lab",   icon: "🪙", shortcut: "Y" },   /* ── CRYPTO_LAB ── */\n'
         '    { path: "/tv-alerts",    label: "TV Alerts",    icon: "📡", shortcut: "T", iconOnlyCompact: true },   /* ── TVX_V1_20261007 ── */\n'),
        ('    || (it.path !== "/backtest"\n',
         '    || (it.path !== "/backtest" && it.path !== "/tv-alerts"   /* ── TVX_V1_20261007 ── admin-only */\n'),
        ("              <Link key={item.path} to={item.path} style={{\n",
         "              <Link key={item.path} to={item.path} title={item.label} style={{   /* ── TVX_V1_20261007 ── title */\n"),
        ("                {item.label}\n",
         "                {!(compact && item.iconOnlyCompact) && item.label}   {/* ── TVX_V1_20261007 ── icon-only in compact nav */}\n"),
        ('                  <Route path="/crypto-lab" element={<AdminOnlyCryptoLab />} />   {/* ── CRYPTO_LAB ── */}\n',
         '                  <Route path="/crypto-lab" element={<AdminOnlyCryptoLab />} />   {/* ── CRYPTO_LAB ── */}\n'
         '                  <Route path="/tv-alerts"  element={<AdminOnlyTvAlerts />} />   {/* ── TVX_V1_20261007 ── */}\n'),
        ('b: "/backtest" };', 'b: "/backtest", t: "/tv-alerts" };   // ── TVX_V1_20261007 ── t'),
    ],
}

MIRRORS = {"backend/": "desktop/src-tauri/backend/", "frontend/": "desktop/src-tauri/frontend/"}


def die(msg):
    print(f"\n✖ ABORT: {msg}\nNothing was written.")
    sys.exit(1)


def ok(msg):
    print(f"  ✓ {msg}")


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--dry-run", action="store_true")
    ap.add_argument("--allow-dirty", action="store_true")
    args = ap.parse_args()
    root = Path.cwd()
    print(f"apply_tvx_v1.py — {FENCE}  (repo: {root})\n")

    # 1. location + fence
    for p in list(EDITS):
        if not (root / p).is_file():
            die(f"{p} not found — run from the scalp-app repo root")
    for p in EDITS:
        if FENCE in (root / p).read_text():
            die(f"{FENCE} already present in {p} — already applied")
    for p in PAYLOADS:
        if (root / p).exists():
            die(f"{p} already exists — mixed state (hand-placed file?). Remove it, then run only this script")
    ok("fence absent, no TVX files present")

    # 2. git status on edited files
    try:
        st = subprocess.run(["git", "status", "--porcelain", "--"] + list(EDITS), cwd=root,
                            capture_output=True, text=True, timeout=30).stdout.strip()
    except Exception:
        st = ""
    if st and not args.allow_dirty:
        die(f"edited files have local changes:\n{st}\nCommit/stash them, or re-run with --allow-dirty")
    ok("git status clean on edited files" if not st else f"dirty files allowed:\n{st}")

    # 3. payload integrity
    new_files = {}
    for p, (b64, sha) in PAYLOADS.items():
        data = base64.b64decode(b64)
        if hashlib.sha256(data).hexdigest() != sha:
            die(f"payload checksum mismatch for {p}")
        new_files[p] = data.decode("utf-8")
    ok(f"{len(new_files)} payloads verified (sha256)")

    # 4. anchored edits in memory
    edited = {}
    for p, pairs in EDITS.items():
        s = (root / p).read_text()
        for old, new in pairs:
            n = s.count(old)
            if n != 1:
                die(f"anchor found {n}× (need exactly 1) in {p}:\n    {old.strip()[:110]}")
            s = s.replace(old, new)
        edited[p] = s
    ok(f"{sum(len(v) for v in EDITS.values())} anchors matched exactly once")

    # 5. py_compile
    with tempfile.TemporaryDirectory() as td:
        for p, s in list(new_files.items()) + list(edited.items()):
            if p.endswith(".py"):
                f = Path(td) / p
                f.parent.mkdir(parents=True, exist_ok=True)
                f.write_text(s)
                try:
                    py_compile.compile(str(f), doraise=True)
                except py_compile.PyCompileError as e:
                    die(f"py_compile failed for {p}:\n{e}")
    ok("py_compile: all new/edited Python files")

    # 6. TVX suite in a scratch copy of backend/
    with tempfile.TemporaryDirectory() as td:
        scratch = Path(td) / "backend"
        shutil.copytree(root / "backend" / "app", scratch / "app",
                        ignore=shutil.ignore_patterns("__pycache__", "*.bak-*", "*.pyc"))
        for p, s in list(new_files.items()) + list(edited.items()):
            if p.startswith("backend/"):
                f = scratch / p[len("backend/"):]
                f.parent.mkdir(parents=True, exist_ok=True)
                f.write_text(s)
        r = subprocess.run([sys.executable, "-m", "app.engine.tvx.test_tvx"], cwd=scratch,
                           capture_output=True, text=True, timeout=300)
        tail = "\n".join(r.stdout.strip().splitlines()[-3:])
        if r.returncode != 0:
            print(r.stdout[-6000:], r.stderr[-3000:])
            die("TVX suite failed (output above)")
        passes = r.stdout.count("  PASS  ")
        ok(f"TVX suite: {passes} checks passed ({tail.splitlines()[-1]})")

    # 7. esbuild parse of the JSX
    esb = next((c for c in (root / "frontend/node_modules/.bin/esbuild",
                            root / "desktop/node_modules/.bin/esbuild",
                            root / "desktop/src-tauri/frontend/node_modules/.bin/esbuild") if c.exists()), None)
    if esb is None:
        esb = shutil.which("esbuild")
    if esb:
        with tempfile.TemporaryDirectory() as td:
            for p in ("frontend/src/pages/TvAlerts.jsx", "frontend/src/App.jsx"):
                f = Path(td) / Path(p).name
                f.write_text(new_files.get(p) or edited[p])
                r = subprocess.run([str(esb), str(f), "--loader:.jsx=jsx", "--jsx=automatic",
                                    "--log-level=error"], capture_output=True, text=True, timeout=60)
                if r.returncode != 0:
                    die(f"esbuild could not parse {p}:\n{r.stderr[-2000:]}")
        ok(f"esbuild parsed TvAlerts.jsx + App.jsx ({esb})")
    else:
        print("  ! esbuild not found — JSX parse skipped (build-scalp.sh will compile it)")

    # 8. plan writes (+ mirrors)
    plan = []
    for p, s in list(new_files.items()) + list(edited.items()):
        plan.append((root / p, s, p in edited))
        for src, dst in MIRRORS.items():
            if p.startswith(src) and (root / dst).is_dir():
                mp = root / (dst + p[len(src):])
                plan.append((mp, s, mp.exists()))
    if args.dry_run:
        print("\nDRY RUN — would write:")
        for f, _, b in plan:
            print(f"    {'edit' if b else 'new '}  {f.relative_to(root)}")
        print("\nAll gates passed. Re-run without --dry-run to apply.")
        return

    # 9. staged all-or-nothing writes
    done, backups = [], []
    try:
        for f, s, is_edit in plan:
            if is_edit and f.exists():
                bak = f.with_name(f.name + f".bak-{FENCE}")
                shutil.copy2(f, bak)
                backups.append((f, bak))
            f.parent.mkdir(parents=True, exist_ok=True)
            tmp = f.with_name(f.name + ".tvx-tmp")
            tmp.write_text(s)
            os.replace(tmp, f)
            done.append((f, is_edit))
    except Exception as e:
        for f, is_edit in reversed(done):
            if not is_edit:
                f.unlink(missing_ok=True)
        for f, bak in backups:
            shutil.copy2(bak, f)
            bak.unlink(missing_ok=True)
        die(f"write failed ({e}) — rolled back")

    print("\nWritten:")
    for f, is_edit in done:
        print(f"    {'edit' if is_edit else 'new '}  {f.relative_to(root)}")
    print(f"""
✔ {FENCE} applied.

Next:
  1. git add backend/app/engine/tvx backend/app/api/tvx_routes.py backend/app/api_server.py \\
             frontend/src/pages/TvAlerts.jsx frontend/src/App.jsx docs/TVX_V1.md
     git commit -m "{FENCE}: TV Alerts paper strategy"      (leaves the .bak-{FENCE} files out)
  2. ./desktop/build-scalp.sh both
  3. In tv-relay:  wrangler secret put READ_TOKEN
  4. App → TV Alerts (admin nav, shortcut T) → Settings: relay URL + read token,
     tick "Take paper trades from alerts", Save.
""")


if __name__ == "__main__":
    main()
